
USE master;
GO
IF DB_ID('Healthcare_Source') IS NULL CREATE DATABASE Healthcare_Source;
GO
USE Healthcare_Source;
GO
DROP TABLE IF EXISTS dbo.payments,dbo.claim_lines,dbo.claims,dbo.encounters,dbo.appointments,dbo.patient_insurance,dbo.procedures,dbo.diagnoses,dbo.insurance_plans,dbo.providers,dbo.hospitals,dbo.patients;
GO

CREATE TABLE patients(patient_id INT NOT NULL,first_name VARCHAR(50),last_name VARCHAR(50),date_of_birth DATE,gender VARCHAR(20),phone VARCHAR(20),email VARCHAR(100),address VARCHAR(200),city VARCHAR(50),state VARCHAR(50),registration_date DATE,updated_at DATETIME2);
CREATE TABLE hospitals(hospital_id INT NOT NULL,hospital_name VARCHAR(100),hospital_type VARCHAR(50),city VARCHAR(50),state VARCHAR(50),bed_count INT,status VARCHAR(20),updated_at DATETIME2);
CREATE TABLE providers(provider_id INT NOT NULL,provider_name VARCHAR(100),specialization VARCHAR(100),hospital_id INT,license_number VARCHAR(50),city VARCHAR(50),state VARCHAR(50),status VARCHAR(20),updated_at DATETIME2,provider_type VARCHAR(50));
CREATE TABLE insurance_plans(insurance_plan_id INT NOT NULL,insurance_company VARCHAR(100),plan_name VARCHAR(100),plan_type VARCHAR(50),coverage_percentage DECIMAL(5,2),annual_limit DECIMAL(12,2),status VARCHAR(20),updated_at DATETIME2);
CREATE TABLE patient_insurance(patient_insurance_id INT NOT NULL,patient_id INT,insurance_plan_id INT,policy_number VARCHAR(50),coverage_start_date DATE,coverage_end_date DATE,status VARCHAR(20),updated_at DATETIME2);
CREATE TABLE diagnoses(diagnosis_id INT NOT NULL,diagnosis_code VARCHAR(20),diagnosis_name VARCHAR(150),diagnosis_category VARCHAR(100),severity VARCHAR(30),status VARCHAR(20),updated_at DATETIME2);
CREATE TABLE procedures(procedure_id INT NOT NULL,procedure_code VARCHAR(20),procedure_name VARCHAR(150),procedure_category VARCHAR(100),standard_cost DECIMAL(12,2),status VARCHAR(20),updated_at DATETIME2);
CREATE TABLE appointments(appointment_id BIGINT NOT NULL,patient_id INT,provider_id INT,hospital_id INT,appointment_date DATETIME2,appointment_type VARCHAR(50),appointment_status VARCHAR(30),reason VARCHAR(200),created_at DATETIME2,updated_at DATETIME2);
CREATE TABLE encounters(encounter_id BIGINT NOT NULL,patient_id INT,provider_id INT,hospital_id INT,diagnosis_id INT,procedure_id INT,appointment_id BIGINT,encounter_date DATETIME2,encounter_type VARCHAR(50),encounter_status VARCHAR(30),total_charge DECIMAL(12,2),notes VARCHAR(500),created_at DATETIME2,updated_at DATETIME2);
CREATE TABLE claims(claim_id BIGINT NOT NULL,patient_id INT,encounter_id BIGINT,patient_insurance_id INT,claim_date DATETIME2,submitted_date DATETIME2,processed_date DATETIME2,claim_status VARCHAR(30),claim_amount DECIMAL(12,2),approved_amount DECIMAL(12,2),rejected_amount DECIMAL(12,2),patient_responsibility DECIMAL(12,2),updated_at DATETIME2);
CREATE TABLE claim_lines(claim_line_id BIGINT NOT NULL,claim_id BIGINT,procedure_id INT,diagnosis_id INT,quantity INT,unit_cost DECIMAL(12,2),line_amount DECIMAL(12,2),approved_amount DECIMAL(12,2),rejected_amount DECIMAL(12,2),updated_at DATETIME2);
CREATE TABLE payments(payment_id BIGINT NOT NULL,claim_id BIGINT,patient_id INT,payment_date DATETIME2,payment_amount DECIMAL(12,2),payment_method VARCHAR(30),payment_status VARCHAR(30),transaction_ref VARCHAR(100),updated_at DATETIME2);
GO

DECLARE @n INT; SET @n=1; WHILE @n<=1000 BEGIN INSERT patients VALUES(@n,CASE WHEN @n%97=0 THEN NULL WHEN @n%113=0 THEN '   ' ELSE CHOOSE((@n-1)%10+1,'John','Mary','Robert','Priya','David','Anita','Michael','Rahul','Sarah','Daniel') END,CASE WHEN @n%89=0 THEN NULL ELSE CHOOSE((@n-1)%10+1,'Smith','Johnson','Williams','Sharma','Brown','Patel','Miller','Kumar','Davis','Wilson') END,CASE WHEN @n%101=0 THEN DATEADD(YEAR,2,GETDATE()) WHEN @n%131=0 THEN NULL ELSE DATEADD(DAY,-(@n*173%25000),GETDATE()) END,CASE WHEN @n%83=0 THEN 'UNKNOWN' WHEN @n%137=0 THEN NULL ELSE CHOOSE((@n-1)%3+1,'Male','Female','Other') END,CASE WHEN @n%107=0 THEN '12345' ELSE CONCAT('9',RIGHT(CONCAT('000000000',@n),9)) END,CASE WHEN @n%109=0 THEN 'bad-email' ELSE CONCAT('patient',@n,'@example.com') END,CONCAT(@n,' Healthcare Avenue'),CASE WHEN @n%103=0 THEN NULL ELSE CHOOSE((@n-1)%5+1,'Hyderabad','Bangalore','Chennai','Mumbai','Pune') END,CHOOSE((@n-1)%5+1,'Telangana','Karnataka','Tamil Nadu','Maharashtra','Maharashtra'),CASE WHEN @n%127=0 THEN DATEADD(DAY,30,GETDATE()) ELSE DATEADD(DAY,-(@n*37%3000),GETDATE()) END,CASE WHEN @n%79=0 THEN NULL ELSE DATEADD(MINUTE,-@n*7,SYSDATETIME()) END); SET @n+=1 END;

SET @n=1; WHILE @n<=100 BEGIN INSERT hospitals VALUES(@n,CASE WHEN @n%29=0 THEN NULL ELSE CONCAT('CityCare Hospital ',@n) END,CASE WHEN @n%31=0 THEN 'UNKNOWN' WHEN @n%47=0 THEN NULL ELSE CHOOSE((@n-1)%4+1,'General','Specialty','Teaching','Community') END,CHOOSE((@n-1)%5+1,'Hyderabad','Bangalore','Chennai','Mumbai','Pune'),CHOOSE((@n-1)%5+1,'Telangana','Karnataka','Tamil Nadu','Maharashtra','Maharashtra'),CASE WHEN @n%23=0 THEN -50 WHEN @n%43=0 THEN 0 WHEN @n%53=0 THEN NULL ELSE 50+(@n*17%450) END,CASE WHEN @n%19=0 THEN 'UNKNOWN' WHEN @n%43=0 THEN NULL ELSE CHOOSE((@n-1)%2+1,'Active','Inactive') END,CASE WHEN @n%61=0 THEN NULL ELSE DATEADD(DAY,-(@n%500),SYSDATETIME()) END); SET @n+=1 END;

SET @n=1; WHILE @n<=500 BEGIN INSERT providers VALUES(@n,CASE WHEN @n%71=0 THEN NULL ELSE CONCAT('Provider ',@n) END,CASE WHEN @n%61=0 THEN 'UNKNOWN' WHEN @n%97=0 THEN NULL ELSE CHOOSE((@n-1)%6+1,'Cardiology','Neurology','Orthopedics','Pediatrics','General Medicine','Oncology') END,CASE WHEN @n%67=0 THEN 9999 WHEN @n%101=0 THEN NULL ELSE (@n-1)%100+1 END,CASE WHEN @n%73=0 THEN NULL ELSE CONCAT('LIC-',RIGHT(CONCAT('00000',@n),5)) END,CHOOSE((@n-1)%5+1,'Hyderabad','Bangalore','Chennai','Mumbai','Pune'),CHOOSE((@n-1)%5+1,'Telangana','Karnataka','Tamil Nadu','Maharashtra','Maharashtra'),CASE WHEN @n%59=0 THEN 'UNKNOWN' WHEN @n%89=0 THEN NULL ELSE CHOOSE((@n-1)%2+1,'Active','Inactive') END,CASE WHEN @n%107=0 THEN NULL ELSE DATEADD(DAY,-(@n%400),SYSDATETIME()) END,CASE WHEN @n%79=0 THEN NULL WHEN @n%113=0 THEN 'UNKNOWN' ELSE CHOOSE((@n-1)%4+1,'Physician','Surgeon','Nurse Practitioner','Physician Assistant') END); SET @n+=1 END;

SET @n=1; WHILE @n<=50 BEGIN INSERT insurance_plans VALUES(@n,CHOOSE((@n-1)%5+1,'HealthSecure','MediCare Plus','WellLife','Prime Health','National Health'),CASE WHEN @n%17=0 THEN NULL ELSE CONCAT('Plan ',@n) END,CASE WHEN @n%19=0 THEN 'UNKNOWN' WHEN @n%29=0 THEN NULL ELSE CHOOSE((@n-1)%4+1,'Individual','Family','Employer','Government') END,CASE WHEN @n%13=0 THEN 125 WHEN @n%31=0 THEN -10 WHEN @n%37=0 THEN NULL ELSE 60+(@n*3%41) END,CASE WHEN @n%17=0 THEN -5000 WHEN @n%43=0 THEN NULL ELSE 50000+(@n*791%150000) END,CASE WHEN @n%11=0 THEN 'UNKNOWN' WHEN @n%27=0 THEN NULL ELSE CHOOSE((@n-1)%2+1,'Active','Inactive') END,CASE WHEN @n%7=0 THEN NULL ELSE DATEADD(DAY,-(@n%300),SYSDATETIME()) END); SET @n+=1 END;

SET @n=1; WHILE @n<=1500 BEGIN INSERT patient_insurance VALUES(@n,CASE WHEN @n%73=0 THEN 999999 WHEN @n%89=0 THEN NULL ELSE (@n-1)%1000+1 END,CASE WHEN @n%61=0 THEN 999999 WHEN @n%101=0 THEN NULL ELSE (@n-1)%50+1 END,CASE WHEN @n%83=0 THEN NULL WHEN @n%97=0 THEN 'BAD' ELSE CONCAT('POL-',RIGHT(CONCAT('000000',@n),6)) END,CASE WHEN @n%71=0 THEN NULL ELSE DATEADD(DAY,-(@n%1500),GETDATE()) END,CASE WHEN @n%67=0 THEN DATEADD(DAY,-500,GETDATE()) WHEN @n%79=0 THEN NULL ELSE DATEADD(DAY,365+(@n%1000),DATEADD(DAY,-(@n%1500),GETDATE())) END,CASE WHEN @n%53=0 THEN 'UNKNOWN' WHEN @n%107=0 THEN NULL ELSE CHOOSE((@n-1)%2+1,'Active','Inactive') END,CASE WHEN @n%113=0 THEN NULL ELSE DATEADD(DAY,-(@n%300),SYSDATETIME()) END); SET @n+=1 END;

SET @n=1; WHILE @n<=100 BEGIN INSERT diagnoses VALUES(@n,CASE WHEN @n%23=0 THEN NULL WHEN @n%37=0 THEN 'BADCODE' ELSE CONCAT('DX-',RIGHT(CONCAT('000',@n),3)) END,CASE WHEN @n%29=0 THEN NULL ELSE CONCAT('Synthetic Diagnosis ',@n) END,CHOOSE((@n-1)%5+1,'Cardiac','Neurological','Musculoskeletal','Respiratory','General'),CASE WHEN @n%17=0 THEN 'UNKNOWN' WHEN @n%31=0 THEN NULL ELSE CHOOSE((@n-1)%4+1,'Low','Moderate','High','Critical') END,CASE WHEN @n%19=0 THEN 'UNKNOWN' WHEN @n%41=0 THEN NULL ELSE CHOOSE((@n-1)%2+1,'Active','Inactive') END,CASE WHEN @n%47=0 THEN NULL ELSE DATEADD(DAY,-(@n%500),SYSDATETIME()) END); SET @n+=1 END;

SET @n=1; WHILE @n<=150 BEGIN INSERT procedures VALUES(@n,CASE WHEN @n%31=0 THEN NULL WHEN @n%43=0 THEN 'BADPROC' ELSE CONCAT('PROC-',RIGHT(CONCAT('000',@n),3)) END,CASE WHEN @n%37=0 THEN NULL ELSE CONCAT('Synthetic Procedure ',@n) END,CHOOSE((@n-1)%5+1,'Consultation','Diagnostic','Surgical','Laboratory','Imaging'),CASE WHEN @n%23=0 THEN -100 WHEN @n%41=0 THEN NULL ELSE 500+(@n*127%20000) END,CASE WHEN @n%29=0 THEN 'UNKNOWN' WHEN @n%47=0 THEN NULL ELSE CHOOSE((@n-1)%2+1,'Active','Inactive') END,CASE WHEN @n%53=0 THEN NULL ELSE DATEADD(DAY,-(@n%500),SYSDATETIME()) END); SET @n+=1 END;

DECLARE @n INT = 1; WHILE @n <= 5000 BEGIN INSERT INTO dbo.appointments VALUES (100000+@n,CASE WHEN @n%97=0 THEN 999999 WHEN @n%113=0 THEN NULL ELSE (@n-1)%1000+1 END,CASE WHEN @n%89=0 THEN 999999 WHEN @n%127=0 THEN NULL ELSE (@n-1)%500+1 END,CASE WHEN @n%83=0 THEN 999999 WHEN @n%131=0 THEN NULL ELSE (@n-1)%100+1 END,CASE WHEN @n%107=0 THEN DATEADD(DAY,30,GETDATE()) WHEN @n%139=0 THEN NULL ELSE DATEADD(DAY,-(@n%900),SYSDATETIME()) END,CASE WHEN @n%73=0 THEN 'UNKNOWN' WHEN @n%149=0 THEN NULL ELSE CHOOSE((@n-1)%4+1,'Consultation','Follow-up','Diagnostic','Emergency') END,CASE WHEN @n%61=0 THEN 'UNKNOWN' WHEN @n%97=0 THEN NULL ELSE CHOOSE((@n-1)%5+1,'SCHEDULED','RESCHEDULED','COMPLETED','CANCELLED','NO SHOW') END,CASE WHEN @n%101=0 THEN NULL ELSE CHOOSE((@n-1)%5+1,'Routine checkup','Pain','Follow-up','Diagnostic review','New symptoms') END,DATEADD(MINUTE,-@n*9,SYSDATETIME()),CASE WHEN @n%79=0 THEN NULL ELSE DATEADD(MINUTE,-@n*5,SYSDATETIME()) END); SET @n+=1; END;

SET @n=1; WHILE @n<=10000 BEGIN INSERT encounters VALUES(200000+@n,CASE WHEN @n%101=0 THEN 999999 WHEN @n%127=0 THEN NULL ELSE (@n-1)%1000+1 END,CASE WHEN @n%89=0 THEN 999999 WHEN @n%137=0 THEN NULL ELSE (@n-1)%500+1 END,CASE WHEN @n%79=0 THEN 999999 WHEN @n%149=0 THEN NULL ELSE (@n-1)%100+1 END,CASE WHEN @n%67=0 THEN 999999 WHEN @n%157=0 THEN NULL ELSE (@n-1)%100+1 END,CASE WHEN @n%71=0 THEN 999999 WHEN @n%163=0 THEN NULL ELSE (@n-1)%150+1 END,CASE WHEN @n%83=0 THEN 999999 WHEN @n%173=0 THEN NULL ELSE 100000+(@n-1)%5000+1 END,CASE WHEN @n%97=0 THEN DATEADD(DAY,10,SYSDATETIME()) WHEN @n%109=0 THEN NULL ELSE DATEADD(DAY,-(@n%1000),SYSDATETIME()) END,CASE WHEN @n%73=0 THEN 'UNKNOWN' WHEN @n%131=0 THEN NULL ELSE CHOOSE((@n-1)%5+1,'Outpatient','Inpatient','Emergency','Telehealth','Observation') END,CASE WHEN @n%61=0 THEN 'UNKNOWN' WHEN @n%139=0 THEN NULL ELSE CHOOSE((@n-1)%3+1,'Completed','Cancelled','In Progress') END,CASE WHEN @n%53=0 THEN -500 WHEN @n%107=0 THEN NULL ELSE 100+(@n*97%25000) END,CASE WHEN @n%89=0 THEN NULL ELSE CONCAT('Encounter notes for encounter ',@n) END,DATEADD(MINUTE,-@n*3,SYSDATETIME()),CASE WHEN @n%113=0 THEN NULL ELSE DATEADD(MINUTE,-@n*2,SYSDATETIME()) END); SET @n+=1 END;

SET @n=1; WHILE @n<=15000 BEGIN INSERT claims VALUES(500000+@n,CASE WHEN @n%101=0 THEN 999999 WHEN @n%127=0 THEN NULL ELSE (@n-1)%1000+1 END,CASE WHEN @n%89=0 THEN 999999 WHEN @n%137=0 THEN NULL ELSE 200000+(@n-1)%10000+1 END,CASE WHEN @n%83=0 THEN 999999 WHEN @n%149=0 THEN NULL ELSE (@n-1)%1500+1 END,CASE WHEN @n%107=0 THEN NULL ELSE DATEADD(DAY,-(@n%900),SYSDATETIME()) END,CASE WHEN @n%97=0 THEN NULL ELSE DATEADD(DAY,-(@n%880),SYSDATETIME()) END,CASE WHEN @n%79=0 THEN DATEADD(DAY,-((@n%880)+20),SYSDATETIME()) WHEN @n%113=0 THEN NULL ELSE DATEADD(DAY,-(@n%850),SYSDATETIME()) END,CASE WHEN @n%61=0 THEN 'UNKNOWN' WHEN @n%139=0 THEN NULL ELSE CHOOSE((@n-1)%5+1,'Submitted','Approved','Rejected','Partially Approved','Paid') END,CASE WHEN @n%71=0 THEN -100 WHEN @n%131=0 THEN NULL ELSE 500+(@n*83%50000) END,CASE WHEN @n%53=0 THEN -50 WHEN @n%127=0 THEN NULL ELSE 250+(@n*47%45000) END,CASE WHEN @n%47=0 THEN -10 WHEN @n%151=0 THEN NULL ELSE (@n*11%10000) END,CASE WHEN @n%67=0 THEN -25 WHEN @n%157=0 THEN NULL ELSE (@n*7%8000) END,CASE WHEN @n%109=0 THEN NULL ELSE DATEADD(MINUTE,-@n*2,SYSDATETIME()) END); SET @n+=1 END;

SET @n=1; WHILE @n<=30000 BEGIN INSERT claim_lines VALUES(800000+@n,CASE WHEN @n%97=0 THEN 99999999 WHEN @n%113=0 THEN NULL ELSE 500000+(@n-1)%15000+1 END,CASE WHEN @n%79=0 THEN 999999 WHEN @n%131=0 THEN NULL ELSE (@n-1)%150+1 END,CASE WHEN @n%83=0 THEN 999999 WHEN @n%137=0 THEN NULL ELSE (@n-1)%100+1 END,CASE WHEN @n%67=0 THEN 0 WHEN @n%101=0 THEN -1 WHEN @n%149=0 THEN NULL ELSE (@n-1)%5+1 END,CASE WHEN @n%73=0 THEN -100 WHEN @n%127=0 THEN NULL ELSE 100+(@n*41%15000) END,CASE WHEN @n%61=0 THEN -500 WHEN @n%139=0 THEN NULL ELSE 100+(@n*53%30000) END,CASE WHEN @n%59=0 THEN -50 WHEN @n%151=0 THEN NULL ELSE 50+(@n*31%25000) END,CASE WHEN @n%47=0 THEN -20 WHEN @n%157=0 THEN NULL ELSE (@n*13%8000) END,CASE WHEN @n%107=0 THEN NULL ELSE DATEADD(MINUTE,-@n*2,SYSDATETIME()) END); SET @n+=1 END;

SET @n=1; WHILE @n<=20000 BEGIN INSERT payments VALUES(900000+@n,CASE WHEN @n%89=0 THEN 99999999 WHEN @n%127=0 THEN NULL ELSE 500000+(@n-1)%15000+1 END,CASE WHEN @n%101=0 THEN 999999 WHEN @n%139=0 THEN NULL ELSE (@n-1)%1000+1 END,CASE WHEN @n%73=0 THEN NULL ELSE DATEADD(DAY,-(@n%800),SYSDATETIME()) END,CASE WHEN @n%61=0 THEN -100 WHEN @n%113=0 THEN NULL ELSE 100+(@n*71%40000) END,CASE WHEN @n%67=0 THEN 'UNKNOWN' WHEN @n%131=0 THEN NULL ELSE CHOOSE((@n-1)%4+1,'Cash','Card','Bank Transfer','Insurance') END,CASE WHEN @n%79=0 THEN 'UNKNOWN' WHEN @n%149=0 THEN NULL ELSE CHOOSE((@n-1)%3+1,'Successful','Pending','Failed') END,CASE WHEN @n%97=0 THEN NULL WHEN @n%109=0 THEN CONCAT('DUP-REF-',(@n-1)%50+1) ELSE CONCAT('TXN-',RIGHT(CONCAT('000000',@n),6)) END,CASE WHEN @n%107=0 THEN NULL ELSE DATEADD(MINUTE,-@n*2,SYSDATETIME()) END); SET @n+=1 END;

SELECT 'patients' table_name,COUNT(*) record_count FROM patients UNION ALL SELECT 'hospitals',COUNT(*) FROM hospitals UNION ALL SELECT 'providers',COUNT(*) FROM providers UNION ALL SELECT 'insurance_plans',COUNT(*) FROM insurance_plans UNION ALL SELECT 'patient_insurance',COUNT(*) FROM patient_insurance UNION ALL SELECT 'diagnoses',COUNT(*) FROM diagnoses UNION ALL SELECT 'procedures',COUNT(*) FROM procedures UNION ALL SELECT 'appointments',COUNT(*) FROM appointments UNION ALL SELECT 'encounters',COUNT(*) FROM encounters UNION ALL SELECT 'claims',COUNT(*) FROM claims UNION ALL SELECT 'claim_lines',COUNT(*) FROM claim_lines UNION ALL SELECT 'payments',COUNT(*) FROM payments;
GO